import * as THREE from './assets/three.module.js';
import {landPositions,coastPositions} from './assets/land-mesh.js';
export {mountLivingGlobe} from './living-renderer.js';
export function mountGlobe(host,onSelect,options={}){
options={...options,lightweight:options.lightweight||document.documentElement.classList.contains("light-rendering")||document.documentElement.classList.contains("eco-mode")};
const scene=new THREE.Scene();scene.background=new THREE.Color('#071733');const camera=new THREE.PerspectiveCamera(40,1,.1,100);const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));host.replaceChildren(renderer.domElement);renderer.domElement.tabIndex=0;renderer.domElement.setAttribute('role','img');renderer.domElement.setAttribute('aria-label','Globo terrestre 3D. Frecce per ruotare, più e meno per zoom, Invio per scegliere il centro.');
const earth=new THREE.Mesh(new THREE.SphereGeometry(1,64,48),new THREE.MeshPhongMaterial({color:0x06192d,emissive:0x020914,specular:0x37869c,shininess:48}));scene.add(earth);let dead=false;
scene.add(new THREE.HemisphereLight(0xb3eeff,0x071326,2));const keyLight=new THREE.DirectionalLight(0xaff5ff,2.4);keyLight.position.set(4,3,5);scene.add(keyLight);
const landGeometry=new THREE.BufferGeometry();landGeometry.setAttribute('position',new THREE.Float32BufferAttribute(landPositions,3));landGeometry.computeVertexNormals();const land=new THREE.Mesh(landGeometry,new THREE.MeshPhongMaterial({color:0x17485b,emissive:0x092332,specular:0x56dff2,shininess:24,side:THREE.DoubleSide}));scene.add(land);
const coastGeometry=new THREE.BufferGeometry();coastGeometry.setAttribute('position',new THREE.Float32BufferAttribute(coastPositions,3));scene.add(new THREE.LineSegments(coastGeometry,new THREE.LineBasicMaterial({color:0x64e8f5,transparent:true,opacity:.65})));
const gridBase=new THREE.IcosahedronGeometry(1.002,3);const gridGeometry=new THREE.WireframeGeometry(gridBase);gridBase.dispose();const grid=new THREE.LineSegments(gridGeometry,new THREE.LineBasicMaterial({color:0x248da6,transparent:true,opacity:options.lightweight ? .06 : .14}));scene.add(grid);
if(!options.lightweight){const glow=new THREE.Mesh(new THREE.SphereGeometry(1.065,48,32),new THREE.ShaderMaterial({transparent:true,depthWrite:false,side:THREE.BackSide,blending:THREE.AdditiveBlending,vertexShader:'varying vec3 normalView;varying vec3 positionView;void main(){normalView=normalize(normalMatrix*normal);vec4 p=modelViewMatrix*vec4(position,1.0);positionView=p.xyz;gl_Position=projectionMatrix*p;}',fragmentShader:'varying vec3 normalView;varying vec3 positionView;void main(){float rim=pow(1.0-abs(dot(normalize(normalView),normalize(-positionView))),3.5);gl_FragColor=vec4(0.0,0.75,1.0,rim*0.52);}'}));scene.add(glow)}
const pins=[];const normal=new THREE.Vector3(),up=new THREE.Vector3(0,1,0);
for(const point of options.markers||[]){if(!Number.isFinite(point.lat)||!Number.isFinite(point.lon))continue;const lat=point.lat*Math.PI/180,lon=point.lon*Math.PI/180;normal.set(Math.cos(lat)*Math.cos(lon),Math.sin(lat),-Math.cos(lat)*Math.sin(lon));const pin=new THREE.Mesh(point.type==='shelter'?new THREE.SphereGeometry(.022,10,6,0,Math.PI*2,0,Math.PI/2):new THREE.OctahedronGeometry(.021),new THREE.MeshBasicMaterial({color:point.type==='shelter'?0x00f0ff:0xffcf82}));pin.position.copy(normal).multiplyScalar(1.027);pin.quaternion.setFromUnitVectors(up,normal);pin.userData.point=point;scene.add(pin);pins.push(pin)}
if(options.lightweight){renderer.setPixelRatio(1);earth.geometry.dispose();earth.geometry=new THREE.SphereGeometry(1,32,24)}
const initialYaw=options.center?(90+options.center.longitude)*Math.PI/180:1.8,initialPitch=options.center?options.center.latitude*Math.PI/180:.55;
let yaw=initialYaw,pitch=initialPitch,distance=3.2,dragging=false,start=null,moved=false;const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();
function draw(){if(dead)return;camera.position.set(distance*Math.cos(pitch)*Math.sin(yaw),distance*Math.sin(pitch),distance*Math.cos(pitch)*Math.cos(yaw));camera.lookAt(0,0,0);renderer.render(scene,camera)}
function resize(){const width=host.clientWidth,height=width<500?340:440;renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();draw()}const ro=new ResizeObserver(resize);ro.observe(host);
function zoom(delta){distance=THREE.MathUtils.clamp(distance+delta,1.5,5);draw()}
function select(x,y){const rect=renderer.domElement.getBoundingClientRect();pointer.set((x-rect.left)/rect.width*2-1,-(y-rect.top)/rect.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects([earth,...pins])[0];if(!hit)return;if(hit.object.userData.point){options.onMarker?.(hit.object.userData.point);return}const v=hit.point.clone().normalize();const latitude=Math.asin(v.y)*180/Math.PI;let longitude=Math.atan2(-v.z,v.x)*180/Math.PI;if(longitude>180)longitude-=360;onSelect({latitude,longitude})}
const canvas=renderer.domElement;
canvas.onpointerdown=e=>{dragging=true;moved=false;start={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)};
canvas.onpointermove=e=>{if(!dragging)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;yaw-=dx*.008;pitch=THREE.MathUtils.clamp(pitch+dy*.008,-1.45,1.45);start={x:e.clientX,y:e.clientY};draw()};
canvas.onpointerup=e=>{dragging=false;if(!moved)select(e.clientX,e.clientY)};canvas.onpointercancel=()=>dragging=false;
canvas.onwheel=e=>{e.preventDefault();zoom(Math.sign(e.deltaY)*.15)};
canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','Enter'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')yaw-=.12;if(e.key==='ArrowRight')yaw+=.12;if(e.key==='ArrowUp')pitch=Math.min(1.45,pitch+.12);if(e.key==='ArrowDown')pitch=Math.max(-1.45,pitch-.12);if(e.key==='+')zoom(-.3);if(e.key==='-')zoom(.3);if(e.key==='Enter'){const r=canvas.getBoundingClientRect();select(r.left+r.width/2,r.top+r.height/2)}draw()};
const buttons=[];function bind(id,fn){const b=document.querySelector(id);if(b){b.onclick=fn;buttons.push(b)}}bind('#globe-in',()=>zoom(-.35));bind('#globe-out',()=>zoom(.35));bind('#globe-reset',()=>{yaw=initialYaw;pitch=initialPitch;distance=3.2;draw()});
const continents=[[48,12],[3,20],[35,100],[45,-100],[-15,-60],[-25,135],[-80,0]];document.querySelectorAll('[data-continent]').forEach(b=>{b.onclick=()=>{const [lat,lon]=continents[+b.dataset.continent];pitch=lat*Math.PI/180;yaw=(90+lon)*Math.PI/180;distance=2.8;draw();onSelect({latitude:lat,longitude:lon})};buttons.push(b)});resize();
return ()=>{dead=true;ro.disconnect();buttons.forEach(b=>b.onclick=null);scene.traverse(o=>{o.geometry?.dispose();if(o.material)for(const m of [o.material].flat())m.dispose()});renderer.dispose();renderer.forceContextLoss();canvas.remove()};
}
